query:
MATCH (m:Museo {name:"Quadreria dei Girolamini"})-[:SITUATO_IN]-(c:Città {name:"Napoli"})
SET m.biglietto = "biglietto intero 5€, ridotto 2€", m.orari = "dal martedì al venerdì, ore 10.00 – 18.30 con ultimo ingresso alle 17.45;
sabato, domenica e festivi ore 08.30 – 13.30 con ultimo ingresso alle 12.45;
chiusa i lunedì"
RETURN m
